    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    ordered = []
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            ordered.append(cls)
            for b in minimalBases(cls.__bases__):
                if b not in seen:
                    seen.add(b)
                    ordered.append(b)
