    if not isinstance(params, (dict, list)):
        raise TypeError("Invalid parameter type: should be dict or list, got {}".format(type(params)))

    if isinstance(params, dict):
        if self.in_style != self.PARAM_NAMED:
            raise ValueError("Invalid parameter dictionary for {} style parameters".format(self.in_style))
        params = list(params.items())
    elif isinstance(params, list):
        if self.in_style != self.PARAM_ORDINAL:
            raise ValueError("Invalid parameter list for {} style parameters".format(self.in_style))
    else:
        raise ValueError("Unsupported parameter type: {}".format(type(params)))

    db_params = {
        self.PARAM_MARKER: []  # type: Union[List[Any], Dict[str, Any]]
    }

    # Replace the in-style parameters with out-style parameters
    for param in params:
        if isinstance(param, tuple):
            # Named parameter
            if self.in_style != self.PARAM_NAMED:
                raise ValueError("Cannot use named parameters as in-style parameters")
            if not isinstance(param[0], str):
                raise ValueError("Invalid parameter name: should be str, got {}".format(type(param[0])))
            db_params[param[0]] = param[1]
            param = self.PARAM_MARKER
        else:
            # Ordinal parameter
            if self.in_style != self.PARAM_ORDINAL:
                raise ValueError("Cannot use ordinal parameters as in-style parameters")
        sql = sql.replace(param, self.PARAM_MARKER, 1)
        db_params[self.PARAM_MARKER].append(param)

    return sql, db_params

