    if 'implementation' not in spec or len(spec['implementation']) == 0:
        raise IRValidatorException('Implementation details are missing.')

    # Return the loaded spec file as a dictionary
    return spec

def validate_from_file(yaml_file):
    with open(yaml_file) as f:
        data = yaml.load(f)

    if data is None:
        raise ValueError("No data found in file")

    for field in cls.mandatory_fields:
        if field not in data:
            raise IRValidatorException(f"Mandatory field '{field}' is missing in file")

    return data

def get_spec_defaults(self):
        """
        Resolve arguments' values from the spec and other sources.

        Returns:
            dict: A dictionary containing the resolved argument values.
        """
        defaults = {}
        for arg in self.args:
            # 1. Check if argument name is specified in spec.
            if arg.name in self.spec:
                # 2. If yes, set the argument's value from spec.
                defaults[arg.name] = self.spec[arg.name]
            else:
                # 3. Check if argument has a default value set.
                if arg.has_default():
                    # 4. If yes, set the argument's value to its default.
                    defaults[arg.name] = arg.get_default()
                else:
                    # 5. If no, set the argument's value to None.
                    defaults[arg.name] = None
        return defaults

