def get_conditionally_required_args(command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    conditional_required_args = []
    for arg in options_spec:
        if "required_when" in arg:
            required = False
            for condition in arg["required_when"]:
                if condition in args:
                    required = True
                    break
            if required:
                conditional_required_args.append(arg["name"])
    return conditional_required_args

